  "privacyThirdTitle": "Third-Party Services",
  "privacyUpdated": "Last Updated: 2026-09-18 · Aligned with <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/Legal/privacy.md\" target=\"_blank\" rel=\"noopener\" class=\"text-amber-300 underline\">docs/Legal/privacy.md</a>",
